// External HTTPS Image URLs (No local source files needed)
const recaptchaData = [
    {
        id: 1,
        src: 'data:image/jpeg;base64,',
        isCorrect: true
    },
    {
        id: 2,
        src: 'data:image/jpeg;base64,',
        isCorrect: false
    },
    {
        id: 3,
        src: 'data:image/jpeg;base64,',
        isCorrect: true
    },
    {
        id: 4,
        src: 'data:image/jpeg;base64,',
        isCorrect: false
    },
    {
        id: 5,
        src: 'data:image/jpeg;base64,',
        isCorrect: true
    },
    {
        id: 6,
        src: 'data:image/jpeg;base64,',
        isCorrect: false
    },
    {
        id: 7,
        src: 'data:image/jpeg;base64,',
        isCorrect: true
    },
    {
        id: 8,
        src: 'data:image/jpeg;base64,',
        isCorrect: false
    },
    {
        id: 9,
        src: 'data:image/jpeg;base64,',
        isCorrect: false
    },
];

const selectedIndices = new Set();

function initRecaptchaGrid() {
    const gridContainer = document.querySelector('#recaptcha-grid');
    if (!gridContainer) return;

    gridContainer.innerHTML = '';

    recaptchaData.forEach((item, index) => {
        const tile = document.createElement('div');
        tile.classList.add('grid-item');
        tile.dataset.index = index;

        const img = document.createElement('img');
        img.src = item.src;
        img.alt = 'Tile option';

        tile.appendChild(img);

        // Toggle tile selection on click
        tile.addEventListener('click', () => {
            if (selectedIndices.has(index)) {
                selectedIndices.delete(index);
                tile.classList.remove('selected');
            } else {
                selectedIndices.add(index);
                tile.classList.add('selected');
            }
        });

        gridContainer.appendChild(tile);
    });
}

// Render grid on load
document.addEventListener('DOMContentLoaded', initRecaptchaGrid);

// Verify Button Handler
document.querySelector('#verify-captcha-btn').addEventListener('click', (e) => {
    e.preventDefault();

    const errorElement = document.querySelector('#recaptcha-error');

    // Check if every birthday girl photo is selected AND no false photos are selected
    const isCorrect = recaptchaData.every((item, index) => {
        const isSelected = selectedIndices.has(index);
        return item.isCorrect ? isSelected : !isSelected;
    });

    if (isCorrect) {
        if (errorElement) errorElement.classList.add('hidden');

        // Transition to the next page
        navigateSections('#image-selection-block', '#cake', true, '#loading-messages-2');
        document.body.classList.remove('has-gradient');
        document.body.style.padding = '0';
        document.documentElement.style.padding = '0';
    } else {
        // Show error message
        if (errorElement) errorElement.classList.remove('hidden');
    }
});